mapper.select:
SELECT e.id
FROM enrollment e
WHERE e.school_id = #{schoolId}
  AND e.offering_id = #{offeringId}
  AND e.student_id = #{studentId}
  AND e.status = 'ENROLLED'
  AND e.enrolled_at <= #{sessionStartsAt}
FOR UPDATE

SELECT COUNT(*)
FROM leave_request
WHERE session_id = #{sessionId}
  AND student_id = #{studentId}
  AND status IN ('PENDING', 'APPROVED')

SELECT e.id
FROM enrollment e
WHERE e.school_id = #{schoolId}
  AND e.offering_id = #{offeringId}
  AND e.student_id = #{studentId}
  AND e.status = 'ENROLLED'
FOR UPDATE

SELECT FROM attendance_correction_request cr JOIN school s ON s.id = cr.school_id JOIN course_offering o ON o.id = cr.offering_id JOIN course c ON c.id = o.course_id JOIN lesson_session ls ON ls.id = cr.session_id JOIN attendance a ON a.id = cr.attendance_id JOIN student st ON st.id = cr.student_id JOIN sys_user requester ON requester.id = cr.requested_by LEFT JOIN sys_user reviewer ON reviewer.id = cr.reviewed_by LEFT JOIN sys_user canceler ON canceler.id = cr.canceled_by
AND cr.school_id = #{schoolId} AND o.teacher_id = #{teacherId} AND cr.offering_id = #{offeringId} AND cr.session_id = #{sessionId} AND cr.status = #{status}
ORDER BY cr.requested_at DESC, cr.id DESC
